function s(e){return String(e).padStart(2,"0")}function o(e=new Date){return`${e.getFullYear()}-${s(e.getMonth()+1)}-${s(e.getDate())}`}function u(e){const[t,a,n]=e.split("-").map(Number);return new Date(t,a-1,n)}function c(e,t){const a=u(e);return a.setDate(a.getDate()+t),o(a)}function f(e,t=new Date){const a=o(t);if(e==="week"){const r=new Date(t);return r.setDate(r.getDate()-6),{start:o(r),end:a}}if(e==="all")return{start:"1970-01-01",end:a};const n=new Date(t.getFullYear(),t.getMonth(),1);return{start:o(n),end:a}}function i(e){return u(e).getTime()}function D(e){const t=u(e);return t.setDate(t.getDate()+1),t.getTime()}function h(e){const t=Math.max(0,Math.floor(e/1e3)),a=Math.floor(t/3600),n=Math.floor(t%3600/60),r=t%60;return a>=1?`${a}小时 ${s(n)}分`:n>=10?`${n}分`:n>=1?`${n}分${s(r)}秒`:`${r}秒`}function l(e){const t=Math.max(0,Math.floor(e/1e3)),a=Math.floor(t/3600),n=Math.floor(t%3600/60),r=t%60;return`${s(a)}:${s(n)}:${s(r)}`}function m(e,t,a){return Math.min(a,Math.max(t,e))}export{l as a,c as b,m as c,D as e,h as f,u as p,f as r,i as s,o as t};
